 76	            static ref PLACEHOLDER_PATTERN: Regex = Regex::new(r"\{(/?\.?|//)\}").unwrap();
 77	        }
 78	
 79	        let mut args = Vec::new();
 80	        let mut has_placeholder = false;
 81	
 82	        for arg in input {
 83	            let arg = arg.as_ref();
 84	
 85	            let mut tokens = Vec::new();
 86	            let mut start = 0;
 87	
 88	            for placeholder in PLACEHOLDER_PATTERN.find_iter(arg) {
 89	                // Leading text before the placeholder.
 90	                if placeholder.start() > start {
 91	                    tokens.push(Token::Text(arg[start..placeholder.start()].to_owned()));
 92	                }
 93	
 94	                start = placeholder.end();
 95	
 96	                match placeholder.as_str() {
 97	                    "{}" => tokens.push(Token::Placeholder),
 98	                    "{.}" => tokens.push(Token::NoExt),
 99	                    "{/}" => tokens.push(Token::Basename),
100	                    "{//}" => tokens.push(Token::Parent),
101	                    "{/.}" => tokens.push(Token::BasenameNoExt),
102	                    _ => unreachable!("Unhandled placeholder"),
103	                }
104	
105	                has_placeholder = true;
106	            }
107	
108	            // Without a placeholder, the argument is just fixed text.
109	            if tokens.is_empty() {
110	                args.push(ArgumentTemplate::Text(arg.to_owned()));
111	                continue;
112	            }
113	
114	            if start < arg.len() {
115	                // Trailing text after last placeholder.
116	                tokens.push(Token::Text(arg[start..].to_owned()));
117	            }
118	
119	            args.push(ArgumentTemplate::Tokens(tokens));
120	        }
